## 2. Tester sans moteur réel

### 2.1 Ce qui existe

- `internal/docker` : toute invocation passe par `dockerRunner` (`exec.go`). Les tests
  installent `stubRunner` (`exec_test.go`), qui répond selon le premier argument, et
  `useEngine(t, "podman")` épingle le moteur.
- `internal/ui/oci_resources/faketool_test.go`, `internal/scan` (`dependencies_test.go`)
  et `internal/nexusbench/helper_process_test.go` mettent chacun **leur propre** faux
  binaire sur le `PATH` : le binaire de test se fait passer pour l'outil. Ce sont trois
  implémentations du même motif.
- `internal/nexusfixture` et `fakenexus` : échanges enregistrés contre un vrai Nexus, un
  fichier texte par échange, avec caviardage, interdiction de versionner un fichier
  `pending` et test de fixtures périmées. L'enregistrement se fait par un outil de
  développement (`nexus-bench record`) et des tâches `mise` hors CI.
- Gardes d'exécution (`testing.Testing()`) : `credentials.refuseUnderTest` et
  `ports.refuseRealSignalUnderTest`. Gardes statiques : `TestContainerGuard*`,
  `TestOnlyRealOSSendsASignal`, `TestHostStoreGuard*`, et `nexusbench/guard_test.go`
  (`requireBench`, exec seulement dans les fichiers autorisés).

Trous constatés :

- **Aucune garde n'empêche un test d'atteindre le vrai `docker` ou `podman`.** `cliRunner`
  exécute `engine.Current().Binary` sans contrôle. `containers_test.go` évite seulement
  les touches qui appellent `detectShell` : un `exec` synchrone dans `Update`
  (`containers/update.go:379`).
- Le binaire du moteur est lancé hors de `internal/docker` : `containers/update.go:379`,
  `:402`, `:417`, `containers/sources.go:125`, `scan/scanner.go:472` et
  `scan/container_run.go:55`.
- Incohérence documentaire à trancher : `network.md` dit qu'aucune mesure n'a été faite
  contre un vrai Podman, alors que le commentaire de `internal/engine/engine.go` cite une
  mesure sur Podman 5.7.0 (trois gabarits divergents). À vérifier.

package docker

import (
	"os"
	"path/filepath"
	"runtime"
	"strings"
	"testing"

	"github.com/anthnel/devdesk/internal/engine"
)

// The whole point of §3.67: nothing in this package names an engine any more.
// These tests pin the three places where that could regress — the message when
// the binary is missing, the label a failure is reported under, and the
// templates the parsed calls ask for.

func TestTheMissingBinaryIsNamedAfterTheConfiguredEngine(t *testing.T) {
	stub(t, &stubRunner{missing: true})
	useEngine(t, engine.Podman)

	err := requireEngine()

	if err == nil {
		t.Fatal("requireEngine() returned nil when the engine is absent")
	}
	// Telling someone who pinned podman that docker is missing sends them
	// looking for the wrong thing. The message reaches the footer (Rule 128).
	if !strings.HasPrefix(err.Error(), "podman not found") {
		t.Errorf("requireEngine() = %q, want it to name podman", err)
	}
}

func TestAFailureIsReportedUnderTheConfiguredEngine(t *testing.T) {
	stub(t, &stubRunner{
		output: map[string][]byte{"stop": []byte("Error: no such container\n")},
		err:    map[string]error{"stop": errExit},
	})
	useEngine(t, engine.Podman)

	err := StopContainer("nope")

	if err == nil {
		t.Fatal("StopContainer() returned nil on a failing invocation")
	}
	if want := "podman stop failed: Error: no such container"; err.Error() != want {
		t.Errorf("StopContainer() = %q, want %q", err, want)
	}
}

// The templates come from the shape rather than from a literal at the call
// site. They are the same on both engines today — no measurement has been taken
// (§3.67) — so this asserts the wiring, not the contents: a call that still
// carried its own literal would keep docker's template under podman and nothing
// on screen would say so.
func TestTheParsedCallsAskForTheEnginesOwnTemplates(t *testing.T) {
	tests := []struct {
		name       string
		subcommand string
		call       func()
		want       func(engine.Templates) string
	}{
		{"ps", "ps", func() { _, _ = ListContainers(false) }, func(t engine.Templates) string { return t.PS }},
		{"stats", "stats", func() { _, _ = GetContainerMetrics() }, func(t engine.Templates) string { return t.Stats }},
		{"info", "info", func() { _, _ = FetchCapacity() }, func(t engine.Templates) string { return t.Info }},
		{"network ls", "network", func() { _, _ = ListNetworks() }, func(t engine.Templates) string { return t.NetworkLS }},
		{"volume ls", "volume", func() { _, _ = ListVolumes() }, func(t engine.Templates) string { return t.VolumeLS }},
		{"system df", "system", func() { FetchOCIStats() }, func(t engine.Templates) string { return t.SystemDF }},
	}

	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			s := stub(t, &stubRunner{output: map[string][]byte{tc.subcommand: []byte("")}})
			useEngine(t, engine.Podman)

			tc.call()

			want := tc.want(engine.ShapeFor(engine.Podman).Templates)
			// Every call the function made, not just the last: FetchOCIStats
			// follows its `system df` with a `network ls` for the count that
			// report has no row for.
			if !anyCallCarries(s, want) {
				t.Errorf("%s made %v, want one of them to carry the podman template %q",
					tc.name, allArgs(s), want)
			}
		})
	}
}

func anyCallCarries(s *stubRunner, want string) bool {
	for _, c := range s.calls {
		for _, a := range c.Args {
			if a == want {
				return true
			}
		}
	}
	return false
}

func allArgs(s *stubRunner) [][]string {
	var out [][]string
	for _, c := range s.calls {
		out = append(out, c.Args)
	}
	return out
}

// `system df -v` is the one parsed output with no template: it is a fixed-width
// table read at offsets taken from its header. Under podman the call is not made
// at all, so UniqueSize and Containers stay zero — an absence the table renders
// as a dim "-", rather than numbers sliced out of columns that may not line up.
func TestTheVerboseDiskReportIsNotScrapedUnderPodman(t *testing.T) {
	const imageLS = "sha256:abc\tnginx\tlatest\t140MB\t2026-09-01 10:00:00 +0000 UTC\n"

	t.Run("docker scrapes it", func(t *testing.T) {
		s := stub(t, &stubRunner{output: map[string][]byte{
			"image":  []byte(imageLS),
			"system": []byte(""),
		}})
		useEngine(t, engine.Docker)

		if _, err := ListImages(); err != nil {
			t.Fatalf("ListImages() = %v", err)
		}
		if !ranSubcommand(s, "system") {
			t.Error("docker: `system df -v` was not run")
		}
	})

	t.Run("podman does not", func(t *testing.T) {
		s := stub(t, &stubRunner{output: map[string][]byte{
			"image":  []byte(imageLS),
			"system": []byte(""),
		}})
		useEngine(t, engine.Podman)

		if _, err := ListImages(); err != nil {
			t.Fatalf("ListImages() = %v", err)
		}
		if ranSubcommand(s, "system") {
			t.Error("podman: `system df -v` was run; its table is not known to match docker's")
		}
	})
}

func ranSubcommand(s *stubRunner, subcommand string) bool {
	for _, c := range s.calls {
		if len(c.Args) > 0 && c.Args[0] == subcommand {
			return true
		}
	}
	return false
}

// Both engines run docker-credential-<name>: podman reuses docker's helpers
// rather than naming its own (measured, see credentialHelperPrefix). The real
// runner is used, against a helper script on PATH — a podman-credential-probe
// beside it must never be the one called.
func TestTheCredentialHelperIsDockersUnderEveryEngine(t *testing.T) {
	if runtime.GOOS == "windows" {
		t.Skip("the helper stand-ins are shell scripts")
	}
	dir := t.TempDir()
	write := func(name, body string) {
		if err := os.WriteFile(filepath.Join(dir, name), []byte("#!/bin/sh\n"+body+"\n"), 0o755); err != nil {
			t.Fatal(err)
		}
	}
	write("docker-credential-probe", `echo '{"Username":"alice","Secret":"s3cret"}'`)
	write("podman-credential-probe", `exit 1`)
	t.Setenv("PATH", dir+string(os.PathListSeparator)+os.Getenv("PATH"))

	for _, name := range engine.Names() {
		t.Run(name, func(t *testing.T) {
			stub(t, &stubRunner{}) // restores the runner and the engine
			runner = cliRunner{}
			useEngine(t, name)

			if _, secret, ok := getCredsFromHelper("probe", "registry.example.com"); !ok || secret != "s3cret" {
				t.Errorf("getCredsFromHelper() = %q, %v — want docker-credential-probe's answer", secret, ok)
			}
		})
	}
}
// Package engine names the container engine DevDesk drives — docker or podman —
// and carries everything about it that is not the same between the two.
//
// It exists as its own package rather than as a field of internal/docker
// because internal/scan needs the same answer and does not import
// internal/docker. That is the internal/forge arrangement read one level down:
// the thing every caller shares does not live inside one of its callers.
//
// What a Shape carries is what measurement, not taste, put there (§3.67):
//
//   - the binary, which is the cheap part — internal/docker already funnels
//     every invocation through one runner;
//   - the credential helper prefix and the auth file, because that file is read
//     *and written* directly rather than through the CLI;
//   - the host socket, which is the one path that breaks rather than moves:
//     rootless podman has no /var/run/docker.sock, and its own socket exists
//     only while `podman system service` runs;
//   - the output templates, which are the silent risk. See Templates.
//
// Nothing here sniffs. A shape is declared, the way a forge's is and the way a
// registry's `provider` is (§3.8): a thing is treated as what it says it is.
package engine

import (
	"fmt"
	"os/exec"
	"path/filepath"
	"strings"
	"sync"
)

// Shape is one container engine: what to run, where it keeps its credentials,
// and how to ask it for machine-readable output.
type Shape struct {
	// Name identifies the engine for a config discriminator, a log line, and
	// the word the views show — "docker", "podman".
	Name string

	// Binary is what gets executed. It is the engine's own name for the two
	// declared shapes, and an explicit path when the configuration names one.
	Binary string

	// Templates are the --format strings for every output this application
	// parses.
	Templates Templates
}

// A Shape carries no resolved filesystem path, and that is deliberate: the
// credential file and the socket are looked up through AuthPaths(), AuthPath()
// and HostSocket() at the moment they are needed.
//
// Storing them on the struct was tried and reverted. The shape is built once,
// at package initialisation, so a $HOME or $XDG_RUNTIME_DIR read there is
// frozen before anything else runs — and the socket is worse, since whether it
// exists is the entire question and it can appear (`podman system service`) or
// vanish while the application is up. A cached answer to "where is the file"
// is a cached answer to "does it exist", which is not a thing a shape can know
// once and for all.

// Templates holds one Go template per parsed output.
//
// They are a field of the shape rather than constants at the call sites for a
// reason a real podman went on to confirm: podman implements --format, but
// equality of the *fields* is guaranteed nowhere. A divergence does not
// always raise an error and produce a wrong row (the defect class this
// repository keeps cataloguing, D24, D25, D57) — three of the twelve outputs
// (Info, NetworkLS, SystemDF) name a field podman's template engine does not
// have at all, which fails the command outright instead. `podman info`
// exiting 125 on every poll is what host capacity looked like before this was
// measured.
//
// The other nine match dockerTemplates exactly against that same podman, so
// they stay unified rather than being forked speculatively. What this
// indirection buys is that a future divergence is one line here rather than a
// refactor. Do not collapse it back into constants (§3.67).
//
// The twelfth parsed output has no template and is not here: `system df -v` is
// a fixed-width table scraped by column offsets (internal/docker/images.go),
// because no --format exposes per-image unique size. See ParsesSystemDFVerbose.
type Templates struct {
	// PS lists containers: id, name, image, state, status, created, ports.
	PS string
	// PSState asks for nothing but the state column, to count containers.
	PSState string
	// Stats is the live resource sample, taken with --no-stream.
	Stats string
	// Info is the host's capacity: CPU count and total memory.
	Info string
	// ImageLS lists images: id, repository, tag, size, created.
	ImageLS string
	// ImageInspect reads the size and the registry digests of several images
	// in one call.
	ImageInspect string
	// ImageRepoDigests reads one image's registry digests as JSON.
	ImageRepoDigests string
	// ImageExposedPorts reads an image's EXPOSE declarations as JSON.
	ImageExposedPorts string
	// NetworkLS lists networks: id, name, driver, scope, created.
	NetworkLS string
	// VolumeLS lists volumes: name, driver, mountpoint.
	VolumeLS string
	// SystemDF is the disk report, one row per resource family.
	SystemDF string
	// Version is the client version, for the dashboard's tools table.
	Version string
}

// ParsesSystemDFVerbose reports whether `<engine> system df -v` prints the
// fixed-width "Images space usage:" table internal/docker scrapes for per-image
// unique size and container count.
//
// Only docker is known to. Under podman the columns are left empty rather than
// filled from offsets taken on a header that may not be the same one: a blank
// column reads as an absence, a value sliced out of the wrong column does not.
func (s Shape) ParsesSystemDFVerbose() bool { return s.Name == Docker }

// Engine names, shared with the configuration. They are duplicated in
// internal/config rather than imported from it so that config does not depend
// on this package; TestEveryConfiguredEngineHasAShape holds the two in step,
// the same arrangement the forge names have (§3.6).
const (
	// Docker is what `auto` resolves to when both engines are installed, and
	// what an unrecognised name falls back to.
	Docker = "docker"
	Podman = "podman"
)

// Auto asks for whichever engine is installed. It is the default, so that
// nobody who installed exactly one of the two is asked which one they meant —
// app.secret_backend's precedent (§3.9).
const Auto = "auto"

// dockerTemplates is the set every call in this application was written
// against. podmanTemplates is a copy, and stays a copy until the measurement
// described on Templates has been made.
var dockerTemplates = Templates{
	PS:                "{{.ID}}\t{{.Names}}\t{{.Image}}\t{{.State}}\t{{.Status}}\t{{.CreatedAt}}\t{{.Ports}}",
	PSState:           "{{.State}}",
	Stats:             "{{.ID}}\t{{.CPUPerc}}\t{{.MemUsage}}\t{{.MemPerc}}\t{{.NetIO}}\t{{.BlockIO}}",
	Info:              "{{.NCPU}}\t{{.MemTotal}}",
	ImageLS:           "{{.ID}}\t{{.Repository}}\t{{.Tag}}\t{{.Size}}\t{{.CreatedAt}}",
	ImageInspect:      "{{.ID}}\t{{.Size}}\t{{json .RepoDigests}}",
	ImageRepoDigests:  "{{json .RepoDigests}}",
	ImageExposedPorts: "{{json .Config.ExposedPorts}}",
	NetworkLS:         "{{.ID}}\t{{.Name}}\t{{.Driver}}\t{{.Scope}}\t{{.CreatedAt}}",
	VolumeLS:          "{{.Name}}\t{{.Driver}}\t{{.Mountpoint}}",
	SystemDF:          "{{.Type}}\t{{.TotalCount}}\t{{.Size}}\t{{.Reclaimable}}",
	Version:           "{{.Client.Version}}",
}

// podmanTemplates diverges from dockerTemplates on the three outputs measured
// against a real `podman system service` (§3.67): Info, NetworkLS and
// SystemDF each name a docker-only struct field, and podman's template
// engine — unlike its JSON output, which does carry the docker-shaped field
// under a different name or nested — fails the whole command rather than
// leaving the field blank. `podman info` exits 125 outright, which is what
// broke host capacity reporting for every podman user; the other two return
// no rows.
//
//   - Info: podman nests CPU count and memory under .Host, not at the root.
//     This is also the field `dk setup`'s container-engine question caught,
//     via `docker.FetchCapacity` erroring outright on a genuinely running
//     podman instead of reporting it unreachable for some other reason.
//   - NetworkLS: podman networks carry no scope (docker's Scope column is a
//     swarm concept), and podman's field is called Created, not CreatedAt.
//     The Scope segment is left empty rather than guessed at "local" — the
//     same call HostSocket makes about reporting an absence as a fact.
//   - SystemDF: podman's template-formatted row exposes Total, not the
//     TotalCount its own `--format json` uses for the same count.
//
// The other nine outputs were checked against the same podman and matched
// dockerTemplates exactly, so they are not copied here.
var podmanTemplates = func() Templates {
	t := dockerTemplates
	t.Info = "{{.Host.CPUs}}\t{{.Host.MemTotal}}"
	t.NetworkLS = "{{.ID}}\t{{.Name}}\t{{.Driver}}\t\t{{.Created}}"
	t.SystemDF = "{{.Type}}\t{{.Total}}\t{{.Size}}\t{{.Reclaimable}}"
	return t
}()

// current is the resolved engine. It starts as docker so that every caller has
// a usable answer before the router has read a configuration — which is what
// the application did before this package existed, and what a test that never
// resolves anything should keep seeing.
var (
	currentMu sync.RWMutex
	current   = shapeFor(Docker, Docker)
)

// Current returns the engine in use.
func Current() Shape {
	currentMu.RLock()
	defer currentMu.RUnlock()
	return current
}

// SetCurrent installs the resolved engine. The router calls it once at startup
// and once per context switch, from Update — never from a Cmd (Rule 110).
func SetCurrent(s Shape) {
	currentMu.Lock()
	defer currentMu.Unlock()
	current = s
}

// Names lists the engines a shape is declared for, in the order the
// configuration view cycles them.
func Names() []string { return []string{Docker, Podman} }

// Resolve turns an app.container_engine value into the engine to drive.
//
// The four cases:
//
//	""/"auto"  docker if it is on PATH, else podman, else an error naming both
//	"docker"   pinned; absent is an error
//	"podman"   pinned; absent is an error
//	anything   taken as a path to a binary
//
// A pinned engine that is not installed is an error rather than a fall back to
// the other one. That is credentials.Select's rule (§3.9), and for the same
// reason: someone who asked for podman should not silently get docker, because
// the two do not hold the same containers.
func Resolve(preference string) (Shape, error) {
	switch preference {
	case "", Auto:
		for _, name := range Names() {
			if _, err := exec.LookPath(name); err == nil {
				return shapeFor(name, name), nil
			}
		}
		return Shape{}, fmt.Errorf("no container engine found: neither %s nor %s is on PATH", Docker, Podman)

	case Docker, Podman:
		if _, err := exec.LookPath(preference); err != nil {
			return Shape{}, fmt.Errorf("%s not found: %w", preference, err)
		}
		return shapeFor(preference, preference), nil
	}

	// Anything else is a path. The engine it belongs to is read from the file
	// name — the one place this package guesses, and it guesses about a value
	// the user typed rather than about the world. Getting it wrong costs the
	// auth file location, not the invocation.
	path := preference
	if _, err := exec.LookPath(path); err != nil {
		return Shape{}, fmt.Errorf("container engine %q not found: %w", path, err)
	}
	return shapeFor(engineOfPath(path), path), nil
}

// engineOfPath reads an engine name out of a configured path. Everything that
// is not recognisably podman is treated as docker, which is what an unknown
// docker-compatible CLI (nerdctl, a wrapper script) behaves like.
func engineOfPath(path string) string {
	base := strings.ToLower(filepath.Base(path))
	base = strings.TrimSuffix(base, ".exe")
	if strings.HasPrefix(base, Podman) {
		return Podman
	}
	return Docker
}

// shapeFor builds the shape for one engine, running the given binary.
func shapeFor(name, binary string) Shape {
	if name == Podman {
		return Shape{
			Name:      Podman,
			Binary:    binary,
			Templates: podmanTemplates,
		}
	}
	return Shape{
		Name:      Docker,
		Binary:    binary,
		Templates: dockerTemplates,
	}
}

// ShapeFor returns the declared shape for an engine name, running that name as
// its binary. It answers the configuration view, which needs the shapes before
// anything has been resolved — internal/forge's reason for holding its shapes
// in a table rather than on its backends.
func ShapeFor(name string) Shape { return shapeFor(name, name) }

package docker

import (
	"errors"
	"os/exec"
	"testing"

